QUESTIONS = [

{"id": "sc-166", "v": "dp-kadane", "dom": "whaling", "diff": "E",
 "title": "The Ledger of the Whaler Perseverance",
 "story": "The whaling ship Perseverance has spent three years in the Southern Ocean, and her owners in New Bedford, a firm of cautious Quakers, have asked the first mate to examine the ship's daily ledger with an eye to understanding when the voyage went well and when it went badly. The ledger has one line for each day at sea, in order, from the day the ship left port to the day she returned. Each line records a single whole number: the net result of that day in dollars, counting the value of the oil taken and subtracting the day's costs, such as wages, provisions and repairs. A good day yields a positive figure, a day of calm and no whales yields a negative one, and many days in between yield small figures either way.\n\nThe owners want to identify the best stretch of the voyage: a period of consecutive days, at least one day long, with no day left out in the middle, over which the net results add up to the largest total. They do not care when the stretch began or how long it lasted, only how much it earned. If every single day of the voyage lost money, the best stretch is simply the least bad single day. The owners have heard that some captains choose the best stretch by looking at every possible start and every possible end, but the ledger has some two million lines and the owners' clerk is elderly.\n\nThe mate has noticed that at any given day, the best stretch that finishes on that day is either that day on its own, or that day added to the best stretch that finished on the previous day, whichever is better. That seems to him to be the key to the problem.\n\nThe ship's cat, called Ahab by the crew, once fell overboard and was recovered by a boat hook. The cook's biscuits were so hard that the sailors used them as ballast. The captain read the Psalms aloud on Sundays, but only if the weather allowed.\n\nInput: line one gives N, the number of days. Line two gives the N daily net results, each between -10^9 and 10^9. Output: the largest total of any run of consecutive days.\n\nConstraints: N up to 2 * 10^6.",
 "clues": ["a period of consecutive days, at least one day long, with no day left out in the middle", "the largest total", "the best stretch that finishes on that day is either that day on its own, or that day added to the best stretch that finished on the previous day"],
 "decoys": ["The ship's cat, called Ahab by the crew, once fell overboard", "The cook's biscuits were so hard that the sailors used them as ballast"],
 "core": "Find the run of consecutive values with the largest total, where values may be negative and the run must have at least one value.",
 "gloss": [("whaling", "hunting whales for oil and other products", True), ("provisions", "supplies of food", True), ("ballast", "heavy material carried to steady a ship", True), ("net", "after deductions", True), ("Quakers", "members of a Christian religious group", True)],
 "why": {"ps-longest": "Running totals can solve it, but the story points at the 'best run ending today' relation, the direct approach.", "sw-longest": "No cap or rule bounds the run."},
 "alt": ["ps-longest"],
 "tell": "Best run ending at each day: either start again today, or extend yesterday's best run."},

{"id": "sc-167", "v": "dp-coin", "dom": "penny arcades", "diff": "M",
 "title": "The Token Machine of the Brighton Arcade",
 "story": "On the pier at Brighton there stands a penny arcade of the old school, and its proprietor, a stout and cheerful gentleman by the name of Alfred Pettigrew, has issued a series of brass tokens for use in his machines. The tokens come in several different values, written on their faces in pennies: perhaps a 1, a 5, a 12, a 21, and so on, as Alfred's whims have taken him over the years. There are a great many tokens of each value in the till, as many as are needed, so that no value can ever run out.\n\nAn eccentric lady visits the arcade each Tuesday and insists on paying for her amusements with the fewest tokens possible. Today she wishes to pay exactly A pennies for a go on the mechanical horse-racing game, and no more or less; the machine does not give change. She can use any number of tokens of any value, as many of one value as she likes. Alfred wishes to tell her the fewest number of tokens she needs to hand over so that their values add up to exactly A pennies. If it cannot be done with the denominations he has issued, he must say so.\n\nAlfred has observed something peculiar about his own choice of denominations. When he takes the largest token that fits, then the largest that fits into what remains, and so on, he sometimes gets an answer that is not the fewest. For instance, with tokens of 1, 5 and 12 pennies and a sum of 15, taking the 12 first requires three more 1-pence tokens, four tokens in all, whereas three 5-pence tokens suffice. So the lady's amount cannot simply be paid by grabbing the biggest token each time.\n\nThe arcade has a fortune-telling machine, a brass automaton called Madame Zara, who has a distinctive laugh. The seagulls on the pier have a notorious fondness for chips. A brass band plays on Sundays, weather permitting.\n\nInput: line one gives K and A: the number of denominations and the amount to pay. Line two gives the K denominations. Output: the fewest tokens that sum to exactly A, or -1 if impossible.\n\nConstraints: K up to 100; denominations between 1 and 10^4; A up to 10^6.",
 "clues": ["as many as are needed, so that no value can ever run out", "the fewest number of tokens she needs to hand over so that their values add up to exactly A pennies", "takes the largest token that fits, then the largest that fits into what remains", "with tokens of 1, 5 and 12 pennies and a sum of 15"],
 "decoys": ["The arcade has a fortune-telling machine, a brass automaton called Madame Zara", "The seagulls on the pier have a notorious fondness for chips"],
 "core": "Fewest items, each denomination usable unlimited times, to reach an exact total; the largest-first idea fails.",
 "gloss": [("proprietor", "an owner of a business", True), ("denominations", "the face values of coins or tokens", True), ("eccentric", "unconventional and odd", True), ("automaton", "a mechanical figure", True), ("whims", "sudden fancies", True)],
 "why": {"gr-local": "Taking the largest first is shown wrong by the story's own example.", "dp-knapsack": "Here each value can be used any number of times, not just once."},
 "alt": [],
 "tell": "Unlimited items of fixed values making an exact total: the answer for an amount is one more than the best of the answers for amounts a token smaller."},

{"id": "sc-168", "v": "dp-lis", "dom": "zen gardens", "diff": "M",
 "title": "The Stepping Stones of the Kōrin Garden",
 "story": "The Kōrin Garden in Kyoto is a place of quiet where a gardener, Master Hideo Tanabe, has laid a path of stepping stones across a pond of white gravel raked to resemble water. There are N stones, set out in a long line from the gate to the teahouse, and each stone is a different height above the gravel, in centimetres, because the gardener holds that a rising path leads the mind upward, though not necessarily in a straight, even slope. The heights are recorded in order of position, from the gate to the teahouse. Stones may have the same height as a neighbour, since the quarry supplied them by the cartload.\n\nThe abbot of the neighbouring temple, a man of unusual fastidiousness, has decreed that on the Day of Falling Leaves a procession shall walk to the teahouse, and that each monk of the procession shall step on a number of stones in a manner dictated by the abbot's rule. The rule is this: the monk steps on stones in the order they lie from gate to teahouse, but need not step on every stone; the stones he does tread on must rise in height, each one strictly higher than the one before it. He may skip any stone he pleases, even long runs of them, so long as he never goes backwards towards the gate.\n\nMaster Tanabe has been asked by the abbot how many stones the longest such sequence of treads could contain, so that the abbot may arrange the procession to give the greatest number of monks a seat on the path. He is not interested in which stones form the sequence, only in its length.\n\nThe garden has a famous moss, cultivated over centuries, which visitors are forbidden to touch. A carp in the pond is said to be older than the temple. The tea served in the teahouse is bitter, as it should be.\n\nInput: line one gives N. Line two gives the N heights in order from the gate. Output: the greatest number of stones that can be chosen, in order of position, with strictly rising heights.\n\nConstraints: N up to 10^5; heights up to 10^9. Considering every possible choice of stones to tread on is impossible, since the number of choices doubles with each additional stone.",
 "clues": ["need not step on every stone", "must rise in height, each one strictly higher than the one before it", "never goes backwards towards the gate", "how many stones the longest such sequence of treads could contain"],
 "decoys": ["The garden has a famous moss, cultivated over centuries", "A carp in the pond is said to be older than the temple"],
 "core": "Find the length of the longest strictly rising subsequence (not necessarily consecutive) of a list.",
 "gloss": [("fastidiousness", "great attention to detail and tidiness", True), ("decreed", "ordered officially", True), ("teahouse", "a building for the tea ceremony", True), ("tread", "to step on", True), ("cartload", "the amount a cart carries", True)],
 "why": {"dp-kadane": "That is for consecutive runs; here items may be skipped.", "sw-longest": "A moving frame over neighbours cannot skip stones."},
 "alt": [],
 "tell": "A longest rising selection with skipping allowed: for each stone, the best chain ending there extends the best chain of any lower earlier stone."},

{"id": "sc-169", "v": "dp-grid", "dom": "rice paddies", "diff": "M",
 "title": "The Water Carrier of the Yunnan Terraces",
 "story": "In the mountains of Yunnan, a farming family tends a hillside of rice paddies cut into a rectangular grid, R rows by C columns, each paddy a small square field with its own embankment. Water comes down from a spring at the top left corner of the grid, and must be carried by a family member to the shrine at the bottom right corner, where it is poured out as an offering on the first day of planting. The carrier walks along the embankments, and may step from a paddy only to the paddy immediately to the right of it or the paddy immediately below it, never up the hill or back to the left, because the slope is too steep and the embankments too slippery.\n\nEach paddy has a different effort of crossing, depending on the depth of mud and the height of the embankment: a whole number, positive, written on a stone marker at its corner. The carrier pays the effort of every paddy she stands in, including the first and the last. The grandmother of the family, who has carried the water for fifty years, claims that she can always tell the easiest route by looking at the fields, but her granddaughter, a student of mathematics at the provincial university, suspects that the grandmother's route is not always the best one.\n\nThe family wants to know the smallest total effort for a carrier going from the top left paddy to the bottom right paddy, moving only right or down. They do not want the route itself. The student has also pointed out that the number of different routes through even a modest grid is enormous, and that trying every one is out of the question.\n\nThe terraces are lit at dusk by thousands of tiny oil lamps, a sight that attracts photographers from distant provinces. The family keeps ducks in the flooded paddies. A cousin in the city sends parcels of tea.\n\nInput: line one gives R and C. The next R lines each give C efforts. Output: the smallest total effort of a route from the top-left paddy to the bottom-right paddy using only moves right and down.\n\nConstraints: R and C up to 2000; efforts between 1 and 1000. Because the carrier can only move right or down, the cheapest way to reach any paddy depends only on the cheapest ways to reach the paddy above it and the paddy to its left.",
 "clues": ["may step from a paddy only to the paddy immediately to the right of it or the paddy immediately below it", "pays the effort of every paddy she stands in, including the first and the last", "the number of different routes through even a modest grid is enormous", "the cheapest way to reach any paddy depends only on the cheapest ways to reach the paddy above it and the paddy to its left"],
 "decoys": ["The terraces are lit at dusk by thousands of tiny oil lamps", "The family keeps ducks in the flooded paddies"],
 "core": "Cheapest route from the top-left to the bottom-right of a grid, moving only right or down.",
 "gloss": [("paddy", "a flooded field for growing rice", True), ("embankment", "a raised bank of earth", True), ("shrine", "a holy place", True), ("provincial", "of a region outside the capital", True), ("terraces", "flat steps cut into a hillside", True)],
 "why": {"gr-bfs": "Fewest steps is trivial here, since every route has the same number; cost is what varies.", "sp-dijkstra": "It would work, but the restricted moves make a simpler table enough."},
 "alt": ["sp-dijkstra"],
 "tell": "Moves limited to right and down: the best cost into a cell comes from the cell above or the cell to its left, so fill the table in order."},

{"id": "sc-170", "v": "dp-twostring", "dom": "palaeography", "diff": "H",
 "title": "The Two Copies of the Lindisbrook Gospel",
 "story": "Dr Winifred Aldous, a palaeographer at the university library, has been given two manuscript copies of the same short passage, made by two different scribes in the same monastery. Copied by hand in an age before print, the two versions differ here and there, where a scribe grew tired or misread his exemplar. Dr Aldous has transcribed each passage into a string of letters, without spaces or punctuation, so that the two strings, call them A and B, can be compared character by character. A is the earlier copy and B the later.\n\nShe wishes to measure the distance between the two copies in the following way. A correction is one of three operations on a string: inserting a single letter at any position; deleting a single letter from any position; or replacing one letter by another. The distance between A and B is the smallest number of corrections needed to turn A into B exactly. For example, turning 'kitten' into 'sitting' takes three corrections: replace k by s, replace e by i, and insert g at the end. Dr Aldous does not need to know which corrections they are, only how many.\n\nHer first method was to try every possible sequence of corrections until A became B, and her second was to compare the strings position by position, counting the mismatches. The first method took longer than the lifetime of the manuscript, and the second gave nonsense whenever the scribe had omitted a single early letter, shifting everything after it by one place.\n\nThe library is said to be haunted by the ghost of a bibliophile who died while reading in the rare books room. The reading room's radiators clank alarmingly. A rival palaeographer in Edinburgh has published a fierce review of Dr Aldous's last paper and she has not forgiven him.\n\nInput: line one gives the lengths N and M of A and B. Line two gives A and line three gives B, both in lowercase letters. Output: the smallest number of insertions, deletions and replacements needed to turn A into B.\n\nConstraints: N and M up to 3000. The best distance between a front part of A and a front part of B is built from the distances between slightly shorter front parts.",
 "clues": ["inserting a single letter at any position; deleting a single letter from any position; or replacing one letter by another", "the smallest number of corrections needed to turn A into B exactly", "compare the strings position by position, counting the mismatches", "The best distance between a front part of A and a front part of B is built from the distances between slightly shorter front parts"],
 "decoys": ["The library is said to be haunted by the ghost of a bibliophile", "A rival palaeographer in Edinburgh has published a fierce review"],
 "core": "The minimum number of insertions, deletions and replacements needed to turn one string into another.",
 "gloss": [("palaeographer", "a scholar of ancient handwriting", True), ("exemplar", "the original that a copy is made from", True), ("transcribed", "written out from another form", True), ("manuscript", "a handwritten document", True), ("bibliophile", "a lover of books", True)],
 "why": {"dp-grid": "A table over two strings looks like a grid, but the moves are insert, delete and replace, not right and down with costs.", "ms-match": "No nesting is involved."},
 "alt": [],
 "tell": "Two sequences compared with edit operations: the answer for a pair of front parts comes from the three neighbouring pairs in a table."},

{"id": "sc-171", "v": "dp-knapsack", "dom": "polar expeditions", "diff": "M",
 "title": "The Sledge Load of the Erebus Party",
 "story": "The Erebus Party is a polar expedition preparing for its final push towards the pole, and the leader, Captain Reginald Falconer, must decide which of the N items in the stores the men should drag on the last sledge. Each item has been weighed and has also been assigned a value by the expedition's committee, a whole number reflecting how greatly it contributes to the success of the mission: a theodolite, a tin of pemmican, a spare pair of snow goggles, the Union Jack, and so on. There is exactly one of each item in the stores; there are no duplicates, and the Captain cannot take half of an item or take it twice.\n\nThe sledge, having been built by a local carpenter of limited ambition, cannot haul more than W kilograms in total, and any greater load would see the runners dig into the snow and the men exhausted within a mile. The Captain must therefore choose a set of items, each at most once, with the combined weight not exceeding W, so that the combined value is as great as possible. He does not care how many items are taken or which ones, only that the value is the best the sledge can carry.\n\nThe Captain's second-in-command, Lieutenant Barrow, has proposed that they take the items in order of value per kilogram, starting with the best and continuing until the sledge is full. The Captain, who dislikes the lieutenant, has nevertheless noticed that this can lose. If the sledge may carry 10 kilograms, and there are items of weights 6, 5 and 5 with values 10, 8 and 8, then taking the item with the best ratio first (the first, weight 6, ratio 1.67) blocks the pair of 5-kilogram items, which together are worth 16.\n\nThe expedition's ship is frozen into the ice a hundred miles from the nearest land. The cook has acquired a taste for penguin eggs. A gramophone plays Gilbert and Sullivan on the evenings when the wind is not too fierce.\n\nInput: line one gives N and W. The next N lines each give an item's weight and its value. Output: the greatest total value of a set of items whose total weight is at most W.\n\nConstraints: N up to 200; W up to 10^4; weights up to W; values up to 10^6.",
 "clues": ["exactly one of each item in the stores", "cannot take half of an item or take it twice", "the combined weight not exceeding W, so that the combined value is as great as possible", "take the items in order of value per kilogram"],
 "decoys": ["The cook has acquired a taste for penguin eggs", "A gramophone plays Gilbert and Sullivan on the evenings when the wind is not too fierce"],
 "core": "Choose items, each at most once, within a weight limit, to maximise total value; best-ratio-first can fail.",
 "gloss": [("theodolite", "a surveying instrument for measuring angles", True), ("pemmican", "a mixture of dried meat and fat", True), ("sledge", "a vehicle for sliding over snow", True), ("pole", "the northern or southern end of the earth's axis", True), ("committee", "a group chosen to decide a matter", True)],
 "why": {"gr-local": "Taking the best ratio first is shown wrong by the story's own example.", "dp-coin": "Items here may be taken only once, not repeatedly."},
 "alt": [],
 "tell": "Each item once, weight limit, best value: for each item, the best with a given capacity is either without it or with it plus the best on the smaller capacity."},

{"id": "sc-172", "v": "dp-interval", "dom": "paper mills", "diff": "H",
 "title": "The Reel Mergers at Thornley Mill",
 "story": "The paper mill at Thornley produces newsprint on long reels, and at the end of each week the reels that remain unsold are stored in a line on the warehouse floor, side by side, in the order in which they were made. There are N reels in the line, and each has a known weight in kilograms. The mill's manager, a practical man named Obadiah Sneddon, wishes to join the reels into a single great reel so that the whole stock can be shipped in one consignment to a customer in the capital.\n\nThe only machine that can join reels is a splicing frame in the corner of the warehouse, and it can join only two reels at a time. Moreover, because the warehouse floor is narrow and the reels are heavy, the frame can only be fed two reels that are NEXT TO EACH OTHER in the line: the reels cannot be lifted out and moved. When two neighbouring reels are joined, they become a single reel whose weight is the sum of the two, and which takes their place in the line between the reels that had been on either side of them. The cost of a joining is the weight of the reel it produces, because the heavier the reel, the more power the frame uses.\n\nObadiah wishes to find the least total cost of joining all the reels into one. The order in which neighbouring pairs are joined matters: with three reels of weights 1, 100 and 1, joining the first two (cost 101) and then the result with the third (cost 102) costs 203, whereas joining the last two first (cost 101) and then the first with the result (cost 102) costs the same, but with reels of 10, 1, 10, 1, 10 the costs vary widely depending on the order.\n\nThe warehouse is notorious for mice, and the manager keeps two cats on the payroll. The canteen serves an enormous meat pudding on Thursdays. A union delegate from the city is due to visit next week, and Obadiah has been practising diplomacy.\n\nInput: line one gives N. Line two gives the N reel weights in order of the line. Output: the smallest total cost of joining all reels into one.\n\nConstraints: N up to 400; weights up to 10^4. Considering every possible order of joinings is out of the question, as the number of orders grows astronomically. The best way to join the reels from the i-th to the j-th depends on the best ways of joining shorter stretches within.",
 "clues": ["the frame can only be fed two reels that are NEXT TO EACH OTHER in the line", "the reels cannot be lifted out and moved", "The order in which neighbouring pairs are joined matters", "The best way to join the reels from the i-th to the j-th depends on the best ways of joining shorter stretches within"],
 "decoys": ["The warehouse is notorious for mice, and the manager keeps two cats on the payroll", "A union delegate from the city is due to visit next week"],
 "core": "Merge adjacent items repeatedly into one, minimising total cost, where the best way for a stretch depends on the best ways for shorter stretches inside it.",
 "gloss": [("newsprint", "cheap paper used for newspapers", True), ("splicing", "joining ends together", True), ("consignment", "a batch of goods sent together", True), ("unsold", "not yet purchased", True), ("diplomacy", "skill in handling people tactfully", True)],
 "why": {"hp-greedy": "If any two reels could be joined, always joining the two lightest would work; here only neighbours can be joined, which forbids that.", "dp-knapsack": "There is no weight limit or choice of items."},
 "alt": [],
 "tell": "Only neighbours may be merged, so the last merge splits the line in two: try each split point for every stretch, shortest stretches first."},

{"id": "sc-173", "v": "bk-subsets", "dom": "assay offices", "diff": "M",
 "title": "The Weights of the Goldsmiths' Assay Office",
 "story": "The Assay Office of Goldsmiths' Row has a set of N brass weights of known masses, which the assayer, a precise lady named Perpetua Lovegrove, uses to weigh gold against. Each weight is a whole number of grains, and the weights are laid out in a rack in increasing order of size, with no two weights of the same mass. The office has a ceremonial duty each year: to demonstrate to the Guild all the different ways in which a weight of T grains can be balanced using the brass weights from the rack. A particular way is a collection of weights taken from the rack, any weights may be used at most once in a collection, and the masses in the collection add up to exactly T.\n\nThe Guild has asked for the full list. It does not want a count; it wants every collection written out, one per line, with the masses in each collection given in increasing order, and the collections themselves in no particular order. Two collections are the same if they use the same weights, regardless of the order in which they might be placed on the scale. If there is no way to balance T, the list is empty, and the Guild will be quite satisfied to be told so.\n\nThe assayer has observed that while building a collection, if the weights chosen so far already exceed T, there is no point adding anything more or considering the later weights in the rack, since they are heavier still. She wants to avoid building collections that cannot possibly succeed. She also needs to avoid listing the same collection twice. The rack is small, with at most twenty weights, and T is at most a few hundred grains, so the list of ways will not be very long.\n\nThe Assay Office has a stamp which it uses to hallmark gold, depicting a leopard's head. The Guild's annual feast includes a roast swan, though this custom has recently been questioned. Perpetua's hat is the subject of local legend.\n\nInput: line one gives N and T. Line two gives the N masses in increasing order. Output: each collection on its own line, masses in increasing order; print nothing if no collection exists.\n\nConstraints: N up to 20; masses up to 500; T up to 500.",
 "clues": ["any weights may be used at most once in a collection", "it wants every collection written out", "if the weights chosen so far already exceed T, there is no point adding anything more", "She also needs to avoid listing the same collection twice"],
 "decoys": ["The Assay Office has a stamp which it uses to hallmark gold", "The Guild's annual feast includes a roast swan"],
 "core": "List every selection of items from a small set that adds up to a target, avoiding repeats and cutting off any selection that already exceeds the target.",
 "gloss": [("assayer", "a person who tests the purity of metals", True), ("grains", "a small unit of weight", True), ("hallmark", "an official mark stamped on precious metal", True), ("ceremonial", "used for formal rituals", True), ("collection", "a group of things gathered together", True)],
 "why": {"bt-subsets": "Counting subsets by walking all binary patterns does not list them with early cutoffs; here a pruned search is wanted, and the size is only small enough for it.", "dp-knapsack": "A table could count the ways, but the Guild wants every way written out."},
 "alt": ["bt-subsets"],
 "tell": "List every qualifying selection: pick or skip each item in turn, abandon a path once its total exceeds the target, and undo the pick on return."},

{"id": "sc-174", "v": "bk-perms", "dom": "tea ceremony", "diff": "E",
 "title": "The Seven Utensils of Master Rikyū's School",
 "story": "In the Way of Tea, as taught at a certain school in the old capital of Kyoto, the host arranges the utensils for the ceremony in a precise order, and the order is itself a form of expression, a language in which an experienced guest may read the host's mood. A student of the school, a young woman named Sakura Mizuno, has been set an exercise by her master. She is given N distinct utensils, N being at most eight, among them a tea bowl, a whisk, a scoop, a caddy, a ladle, a kettle and a cloth. Her task is to write out every possible order in which the host might lay out all N utensils, using each utensil exactly once in each arrangement.\n\nThe master insists on completeness. Each different order must appear once and only once in her list, and no order may be missing. The order in which the orders themselves are listed does not matter. If N is three and the utensils are named A, B and C, then she must write six orders: ABC, ACB, BAC, BCA, CAB and CBA. With eight utensils she would have to write out more than forty thousand orders, and the master is a patient man.\n\nSakura's first plan was to write the orders by hand, one after another, hoping to remember which she had done; she very quickly lost track and wrote the order BAC three times. Her second plan, to generate random orders and keep the new ones, was abandoned after she calculated how long it would take to be sure that none were missing. Her friend Haruka suggested a method in which she fixes the first utensil, then fixes the second from those remaining, and so on, laying them out one at a time and picking each up again when she has finished with that arrangement, to try the next option.\n\nThe school's garden is famous for its moss and for the quality of its autumn maples. The tea served at the end of lessons is considerably better than the tea made by students. A wandering monk sometimes stops at the gate for a bowl of rice.\n\nInput: line one gives N. Line two gives N distinct names of utensils. Output: every order of the names, one per line, each name separated by spaces, each order exactly once, in any order of listing.\n\nConstraints: N at most 8.",
 "clues": ["every possible order in which the host might lay out all N utensils, using each utensil exactly once", "Each different order must appear once and only once in her list", "she fixes the first utensil, then fixes the second from those remaining", "picking each up again when she has finished with that arrangement"],
 "decoys": ["The school's garden is famous for its moss and for the quality of its autumn maples", "A wandering monk sometimes stops at the gate for a bowl of rice"],
 "core": "List every ordering of N distinct items, each used exactly once, with no repeats.",
 "gloss": [("caddy", "a small container for tea leaves", True), ("whisk", "a tool for beating", True), ("host", "the person who receives guests", True), ("expression", "a way of showing a feeling or idea", True), ("completeness", "having nothing missing", True)],
 "why": {"bk-subsets": "Selecting some of the items is different from ordering all of them.", "bt-dp": "No cost is being minimised."},
 "alt": [],
 "tell": "All orderings of distinct items: fix one position at a time with any unused item, recurse, then put it back."},

{"id": "sc-175", "v": "bk-board", "dom": "castle garrisons", "diff": "H",
 "title": "The Sentinels of the Courtyard at Rhydd Castle",
 "story": "The garrison commander of Rhydd Castle, a taciturn veteran named Sir Gawain Pritchard, has been given the task of posting N sentinels in the castle's courtyard, which is paved in a square of N by N flagstones. His orders from the lord of the castle are exact. Each sentinel stands on a single flagstone, and a sentinel can see, and so guard against, any intruder who stands anywhere on his own row, anywhere on his own column, and anywhere along either of the two diagonals that pass through his flagstone, as far as the walls of the courtyard. A sentinel does not block the view of another; they see straight through one another, as they were trained to do.\n\nSir Gawain must post all N sentinels so that no sentinel can see any other sentinel: that is, no two sentinels may share a row, a column, or a diagonal. If this cannot be done, he is to report that the courtyard cannot be guarded in this fashion. The lord of the castle, a man whose reasoning is occasionally capricious, wants to know in how many different ways the sentinels can be posted. Two postings are different if at least one flagstone holds a sentinel in one and not in the other. The sentinels themselves are indistinguishable.\n\nThe commander's first idea was to try every possible set of N flagstones from the N-squared available, but even for a courtyard of eight by eight flagstones that is billions of sets. His second idea was to place sentinels one row at a time, working from the top, choosing a column for each row that does not clash with those already posted, and, whenever he finds there is nowhere in a row to put a sentinel, to withdraw the sentinel posted in the row above and move him to a different column.\n\nThe castle is built on a rock above a river that floods in spring. The cook is a Breton, a fact that the garrison's palates have never forgiven. A family of ravens has nested in the keep for generations, and are said to bring good fortune.\n\nInput: a single integer N. Output: the number of distinct ways to post N sentinels with none visible to another.\n\nConstraints: N at most 12.",
 "clues": ["no two sentinels may share a row, a column, or a diagonal", "in how many different ways the sentinels can be posted", "place sentinels one row at a time, working from the top", "withdraw the sentinel posted in the row above and move him to a different column"],
 "decoys": ["The cook is a Breton, a fact that the garrison's palates have never forgiven", "A family of ravens has nested in the keep for generations"],
 "core": "Count the ways to place N pieces on an N by N board so that none share a row, column or diagonal, placing row by row and undoing when stuck.",
 "gloss": [("sentinel", "a guard posted to watch", True), ("flagstone", "a flat paving stone", True), ("capricious", "changing unpredictably", True), ("garrison", "troops stationed in a place", True), ("indistinguishable", "impossible to tell apart", True)],
 "why": {"bk-perms": "Orderings are part of it, but the board's diagonal rule is the heart of the problem and calls for early abandonment of clashing placements.", "gr-flood": "No clusters are counted."},
 "alt": [],
 "tell": "Place pieces one row at a time, reject clashes at once, and undo the last placement when a row has no free square."},

{"id": "sc-176", "v": "gr-reach", "dom": "ice floes", "diff": "M",
 "title": "The Floes of the Breaking Fjord",
 "story": "When the spring thaw comes to the fjord at Narvik, the ice breaks into floes that drift side by side across the water, and every year the schoolchildren of the village perform a traditional crossing, hopping from floe to floe, in an ancient ceremony meant to bring luck to the fishing season. The floes are numbered from 0, the shore floe on which the children begin, to N - 1, the far floe by the harbour wall, which is where they must end. The floes lie in a line across the fjord, each floe next to the one numbered one higher.\n\nThe floes differ in how firmly the child may push off them. Standing on floe i, a child can jump forward a distance of at most A[i] floes: that is, to any floe numbered from i + 1 up to i + A[i], whichever the child prefers, but no further and never backwards. A floe with a push-off of zero is rotten and gives no purchase at all, so that a child standing there cannot jump anywhere. The numbers A[i] are known from the village elders' survey, and a child may choose to jump a shorter distance than the maximum if it suits.\n\nThe schoolmistress, Mrs Solveig Haugen, wants to know the smallest number of jumps with which the whole crossing can be made, from floe 0 to floe N - 1, because the children are small and the water is cold. If the far floe cannot be reached, she wishes to be told so. She does not want the route.\n\nShe has noted that it is not necessary to try all possibilities at each floe. At every step she needs only to ask, among all the floes the children could reach with the jumps taken so far, how far along the line the best of them could take them next, and to commit to a further jump only when the current reach has been exhausted.\n\nThe village is famous for its salted cod and its brass band. A wind from the north has brought a fine drizzle. The fjord's herring have been late this year.\n\nInput: line one gives N. Line two gives N push-off values A[0] to A[N-1]. Output: the smallest number of jumps to reach floe N - 1, or -1 if it cannot be reached.\n\nConstraints: N up to 10^6; A[i] up to 10^5.",
 "clues": ["a child can jump forward a distance of at most A[i] floes", "the smallest number of jumps with which the whole crossing can be made", "among all the floes the children could reach with the jumps taken so far, how far along the line the best of them could take them next", "commit to a further jump only when the current reach has been exhausted"],
 "decoys": ["The village is famous for its salted cod and its brass band", "The fjord's herring have been late this year"],
 "core": "Find the fewest jumps to reach the end of an array where each position allows a jump up to a given length, by tracking the furthest reach.",
 "gloss": [("fjord", "a long narrow sea inlet between cliffs", True), ("floes", "sheets of floating ice", True), ("purchase", "a firm grip", True), ("thaw", "a spell of warmer weather melting ice", True), ("survey", "a detailed examination", True)],
 "why": {"dp-linear": "A table of best counts for each floe would work but costs more than a single sweep tracking the furthest reach.", "gr-bfs": "The same idea appears as layers, but the floes are in a line, and a sweep with a running furthest reach is the direct approach."},
 "alt": ["dp-linear", "gr-bfs"],
 "tell": "Furthest reach: keep how far the current jump can reach and how far the next could reach; when you pass the current limit, count a jump."},

{"id": "sc-177", "v": "gr-pair", "dom": "elephant rides", "diff": "E",
 "title": "The Howdahs of the Jaipur Pageant",
 "story": "At the great winter fair in Jaipur, tourists may ride the festival elephants up the hill to the palace in howdahs, which are the canopied seats strapped to the elephants' backs. Each elephant carries a single howdah, which has room for at most two passengers, and its frame can bear a total weight of at most L kilograms, no more, or the straps will break. The elephant keepers, each of whom is paid by the trip, wish to carry a party of N tourists up the hill in the fewest trips possible. The tourists have all been weighed at the gate, and every tourist weighs at most L, so that any tourist can ride alone if need be.\n\nA trip carries either one tourist or two tourists together, and two tourists may travel together only if their combined weight does not exceed L. Every tourist must be carried up exactly once. The head keeper, an old man named Hari Singh, wishes to know the smallest number of trips that will carry the whole party. He does not mind which tourists ride together, only that no trip is overloaded and that the count of trips is as small as it can be.\n\nHari Singh has noticed a few things. The heaviest tourist in the party is going to be hard to pair, and if the heaviest cannot be paired with the lightest, then there is no one in the party with whom he can be paired, and he must ride alone. The lightest tourist, by contrast, is a good partner for anybody. An apprentice has attempted to pair the tourists in the order in which they arrived, but found that this led to more trips than were needed, because he had paired two light tourists together, leaving two heavy ones who had to ride alone.\n\nThe palace at the top of the hill is pink and has more than nine hundred windows. A snake charmer sets up near the gate, and a boy sells paper kites. The elephants are decorated with painted patterns that take an hour to apply and are gone after a single rain.\n\nInput: line one gives N and L. Line two gives the N tourist weights. Output: the smallest number of trips.\n\nConstraints: N up to 10^6; weights between 1 and L; L up to 10^9. The weights are given in the order the tourists were weighed at the gate, which is no order at all.",
 "clues": ["room for at most two passengers", "two tourists may travel together only if their combined weight does not exceed L", "the smallest number of trips", "if the heaviest cannot be paired with the lightest, then there is no one in the party with whom he can be paired"],
 "decoys": ["The palace at the top of the hill is pink and has more than nine hundred windows", "A snake charmer sets up near the gate, and a boy sells paper kites"],
 "core": "Pair people so that each pair's total is within a limit, using the fewest groups; try pairing the heaviest with the lightest.",
 "gloss": [("howdah", "a canopied seat on an elephant's back", True), ("canopied", "covered by a roof or awning", True), ("passengers", "people carried by a vehicle or animal", True), ("keeper", "a person who looks after animals", True), ("apprentice", "someone learning a trade", True)],
 "why": {"tp-ends": "Two ends are used in the solution, but only after sorting; the underlying decision is the choice of which pairs to make.", "dp-coin": "No amounts are being made up from denominations."},
 "alt": ["tp-ends"],
 "tell": "Sort by weight and pair from the ends: if the lightest fits with the heaviest, they go together; otherwise the heaviest rides alone."},

{"id": "sc-178", "v": "gr-local", "dom": "bookbinding", "diff": "E",
 "title": "The Leather Budget of the Marlowe Bindery",
 "story": "The Marlowe Bindery is a small workshop in the old quarter of the city, where the master bookbinder, Aurelia Fenwick, binds volumes in calf, goatskin and the occasional rare shagreen. The bindery has received a large order, for N books of a particular size, and each book needs one whole hide of leather. At the leather merchant's, the hides are sold individually, each at a price in guineas that depends on the animal, the tanning and the blemishes. The merchant has N hides on his shelves, and every hide will serve for any book equally well, so that Aurelia does not care which hides she buys, only how many.\n\nAurelia has a budget: she has set aside B guineas for leather this month. She wishes to buy as many hides as she can, so as to bind as many books as possible, and she will pay for the hides she buys at the prices marked, with no discount for quantity. She cannot buy part of a hide, and she cannot buy the same hide twice. She is not required to spend all the money; any left over will be put towards the rent.\n\nShe wonders whether it would be better to buy a few expensive hides of finer quality, since they will make the nicer books, but the client's order says only that the books must be bound, and nothing about the leather, and the client is notoriously indifferent to how his books look. Her apprentice, a young man called Cuthbert, proposes buying the hides in the order in which they are displayed on the shelf, stopping when the money runs out; Aurelia dislikes the idea, since an expensive hide at the beginning of the shelf would use up the money for no reason.\n\nThe bindery is fragrant with the smell of paste and old leather. A parrot owned by the neighbouring bookseller can recite the opening lines of the Aeneid. The binder's bone folders are worn smooth by decades of use.\n\nInput: line one gives N and B. Line two gives the N prices. Output: the largest number of hides that can be bought with a total price not exceeding B.\n\nConstraints: N up to 10^6; prices up to 10^9; B up to 10^15. Each hide that is bought removes the same amount of money from the budget as its price, and nothing else changes; and a cheaper hide always leaves at least as much money as a dearer one.",
 "clues": ["She wishes to buy as many hides as she can", "every hide will serve for any book equally well", "she cannot buy the same hide twice", "a cheaper hide always leaves at least as much money as a dearer one"],
 "decoys": ["A parrot owned by the neighbouring bookseller can recite the opening lines of the Aeneid", "The binder's bone folders are worn smooth by decades of use"],
 "core": "With a budget and items of different prices, buy as many items as possible; buy the cheapest first.",
 "gloss": [("shagreen", "a rough leather made from sharkskin or rayskin", True), ("guineas", "an old British currency unit", True), ("tanning", "turning hide into leather", True), ("bindery", "a place where books are bound", True), ("indifferent", "not caring", True)],
 "why": {"dp-knapsack": "Each hide counts for one, so there is no value to maximise beyond the count; a table is overkill.", "hp-greedy": "Always taking the cheapest does not need a structure that keeps changing; sorting once suffices."},
 "alt": [],
 "tell": "Maximise the number of purchases within a budget: take the cheapest first until the money runs out."},
]
